import glob,yaml,json
rows={}
for f in glob.glob('.archon-horizon/roadmap/items/*.yaml'):
    y=yaml.safe_load(open(f)); rows[y['id']]=y
active=[i for i,y in rows.items() if y.get('status')=='active']
tasks=json.load(open('/tmp/tasks.json'))['tasks']
running={t['id'] for t in tasks if t['status']=='running'}
refs={}
for t in tasks:
    for r in (t.get('roadmap_refs') or []): refs.setdefault(r,[]).append((t['id'],t['status']))
print('LIVE TASKS:',sorted(running))
print()
for a in sorted(active):
    y=rows[a]
    md=y.get('metadata') or {}
    own=md.get('owner') or y.get('owner')
    par=md.get('parent') or y.get('parent')
    tr=y.get('task_refs') or []
    held=refs.get(a,[])
    live = (own in running) or any(t in running for t,_ in held) or any(t in running for t in tr)
    # ancestor of live active row?
    kids=[k for k,v in rows.items() if ((v.get('metadata') or {}).get('parent') or v.get('parent'))==a]
    print(('LIVE ' if live else 'ORPH '), a, '| own=',own,'| par=',par,'| task_refs=',tr,'| heldby=',held, '| status_kids=', [(k,rows[k].get('status')) for k in kids])
"
